]

class P(HTMLParser):
    def __init__(self):
        super().__init__()
        self.out=[]
        self.skip=False
    def handle_starttag(self,tag,attrs):
        if tag in ('script','style'):
            self.skip=True
    def handle_endtag(self,tag):
        if tag in ('script','style'):
            self.skip=False
    def handle_data(self,d):
        if self.skip: return
        d=' '.join(d.split())
        if d:
            self.out.append(d)

for fp in files:
    txt=open(fp,encoding='utf-8').read()
    p=P(); p.feed(txt)
    lines=[]
    for t in p.out:
        if t in ('/','•','·'): continue
        # keep meaningful labels and sentences
        if len(t)<2: continue
        lines.append(t)
    # Dedup consecutive
    cleaned=[]
    prev=None
    for t in lines:
        if t==prev: continue
        cleaned.append(t); prev=t
    print('\n===== '+fp+' =====')
    # print first 140 tokens/lines to keep concise
    for i,t in enumerate(cleaned[:140],1):
        print(f'{i:03d}. {t}')
